      ],
      "support_status": "SUFFICIENT",
      "rationale": "P013 supplies the traffic prescription and its controlled-test exception; P012 identifies the canary investigation."
    }
  },
  "signal_basis": {
    "component_id": "C030_SIGNAL_BASIS",
    "value": "The investigation compares slow and ordinary overnight exports under comparable workloads and execution windows, adding canary instrumentation when existing evidence cannot discriminate. It observes changes in predicted phases and overall tail delays alongside failures and unfinished exports, recognizing that instrumentation or test workloads can alter behavior.",
    "scope": "Comparisons use matching information where available and retain limitations for unmatched cases. Canary instrumentation has bounded sampling and logging overhead and excludes document contents.",
    "provenance": {
      "refs": [
